   484→    }
   485→
   486→    #[test]
   487→    fn test_pattern_is_reliable() {
   488→        let mut pattern = RecoveryPattern::new("MemoryLeak".to_string());
   489→        pattern.confidence = 0.75;
   490→        pattern.frequency = 5;
