     2→// 🔮 Phase 6: Predictive Self-Healing - Learning State Machine (Week 1, Day 3-4)
     3→// 패턴 신뢰도 발전 과정 추적 & 상태 전이 로직
     4→// ============================================================================
     5→
     6→// ============================================================================
     7→// LearningState: 5단계 학습 상태
     8→// ============================================================================
     9→// 1. NoData: 아직 데이터 없음 (confidence 0%)
    10→// 2. Observing: 관찰 중 (1-3회, confidence 20-50%)
    11→// 3. Emerging: 패턴 나타남 (4-9회, confidence 50-70%)
    12→// 4. Established: 패턴 확실 (10-29회, confidence 70-90%)
    13→// 5. Mature: 완전 성숙 (30+회, confidence >90%)
    14→
    15→enum LearningState {
    16→    NoData,
    17→    Observing,
    18→    Emerging,
    19→    Established,
    20→    Mature,
    21→}
    22→
    23→impl LearningState {
    24→    fn from_frequency(frequency: u32) -> LearningState {
    25→        match frequency {
    26→            0 => LearningState::NoData,
    27→            1..=3 => LearningState::Observing,
    28→            4..=9 => LearningState::Emerging,
    29→            10..=29 => LearningState::Established,
    30→            30..=u32::MAX => LearningState::Mature,
    31→        }
    32→    }
    33→
    34→    fn to_string(&self) -> String {
    35→        match self {
    36→            LearningState::NoData => "NoData".to_string(),
    37→            LearningState::Observing => "Observing".to_string(),
    38→            LearningState::Emerging => "Emerging".to_string(),
    39→            LearningState::Established => "Established".to_string(),
    40→            LearningState::Mature => "Mature".to_string(),
    41→        }
    42→    }
    43→
    44→    fn confidence_range(&self) -> (f64, f64) {
    45→        // (최소값, 최대값)
    46→        match self {
    47→            LearningState::NoData => (0.0, 0.1),
    48→            LearningState::Observing => (0.2, 0.5),
    49→            LearningState::Emerging => (0.5, 0.7),
    50→            LearningState::Established => (0.7, 0.9),
    51→            LearningState::Mature => (0.9, 1.0),
    52→        }
    53→    }
    54→
    55→    fn min_frequency(&self) -> u32 {
    56→        match self {
    57→            LearningState::NoData => 0,
    58→            LearningState::Observing => 1,
    59→            LearningState::Emerging => 4,
    60→            LearningState::Established => 10,
    61→            LearningState::Mature => 30,
    62→        }
    63→    }
    64→
    65→    fn actionability(&self) -> f64 {
    66→        // 이 상태에서 조치를 취할 때의 신뢰도 가중치 (0.0-1.0)
    67→        match self {
    68→            LearningState::NoData => 0.0,          // 조치 금지
    69→            LearningState::Observing => 0.2,       // 매우 신중한 조치
    70→            LearningState::Emerging => 0.5,        // 조건부 조치
    71→            LearningState::Established => 0.8,     // 적극적 조치
    72→            LearningState::Mature => 1.0,          // 완전한 조치
    73→        }
    74→    }
    75→}
