    12→
    13→struct RecoveryHistoryEntry {
    14→    entry_id: u64,
    15→    timestamp: u64,
    16→    pattern_type: String,
    17→    saturation_before: f64,        // 복구 전 포화도
    18→    saturation_after: f64,         // 복구 후 포화도
    19→    recovery_time_ms: u32,
    20→    success: bool,                 // 복구 성공 여부
    21→    metrics_before: MetricsSnapshot,
    22→    metrics_after: MetricsSnapshot,
    23→    recovery_action: String,       // 실행된 복구 조치
    24→    recovery_confidence: f64,      // 예측 신뢰도 (0.0-1.0)
    25→}
    26→
    27→impl RecoveryHistoryEntry {
    28→    fn new(
    29→        entry_id: u64,
    30→        timestamp: u64,
    31→        pattern_type: String,
    32→        saturation_before: f64,
    33→        recovery_action: String,
    34→    ) -> RecoveryHistoryEntry {
    35→        RecoveryHistoryEntry {
    36→            entry_id,
    37→            timestamp,
    38→            pattern_type,
    39→            saturation_before,
    40→            saturation_after: 0.0,
    41→            recovery_time_ms: 0,
    42→            success: false,
    43→            metrics_before: MetricsSnapshot::new(),
    44→            metrics_after: MetricsSnapshot::new(),
    45→            recovery_action,
    46→            recovery_confidence: 0.0,
    47→        }
    48→    }
    49→
    50→    fn complete_recovery(&mut self, saturation_after: f64, recovery_time_ms: u32, success: bool) {
    51→        self.saturation_after = saturation_after;
    52→        self.recovery_time_ms = recovery_time_ms;
    53→        self.success = success;
    54→    }
    55→
    56→    fn improvement_ratio(&self) -> f64 {
    57→        // 포화도 개선도 (0.0-1.0)
    58→        if self.saturation_before > 0.0 {
    59→            (self.saturation_before - self.saturation_after) / self.saturation_before
    60→        } else {
    61→            0.0
    62→        }
    63→    }
    64→}
