   118→// ============================================================================
   119→// RecoveryHistoryDB: 복구 이력 데이터베이스
   120→// ============================================================================
   121→
   122→struct RecoveryHistoryDB {
   123→    entries: Vec<RecoveryHistoryEntry>,
   124→    max_entries: usize,             // 최대 1,000개 보유
   125→    next_entry_id: u64,
   126→}
   127→
   128→impl RecoveryHistoryDB {
   129→    fn new() -> RecoveryHistoryDB {
   130→        RecoveryHistoryDB {
   131→            entries: Vec::new(),
   132→            max_entries: 1000,
   133→            next_entry_id: 1,
   134→        }
   135→    }
   136→
   137→    fn add_entry(&mut self, mut entry: RecoveryHistoryEntry) -> u64 {
   138→        entry.entry_id = self.next_entry_id;
   139→        self.next_entry_id += 1;
   140→
   141→        self.entries.push(entry);
   142→
   143→        // 최대값 초과 시 가장 오래된 항목 제거
   144→        if self.entries.len() > self.max_entries {
   145→            self.entries.remove(0);
   146→        }
   147→
   148→        self.next_entry_id - 1
   149→    }
   150→
   151→    fn get_entry(&self, entry_id: u64) -> Option<&RecoveryHistoryEntry> {
   152→        self.entries.iter().find(|e| e.entry_id == entry_id)
   153→    }
   154→
   155→    fn get_entries_by_pattern_type(&self, pattern_type: &str) -> Vec<&RecoveryHistoryEntry> {
   156→        self.entries
   157→            .iter()
   158→            .filter(|e| e.pattern_type == pattern_type)
   159→            .collect()
   160→    }
   161→
   162→    fn get_recent_entries(&self, count: usize) -> Vec<&RecoveryHistoryEntry> {
   163→        let start = if self.entries.len() > count {
   164→            self.entries.len() - count
   165→        } else {
   166→            0
   167→        };
   168→        self.entries[start..].iter().collect()
   169→    }
   170→
   171→    fn get_successful_recovery_rate(&self, pattern_type: &str) -> f64 {
   172→        let entries = self.get_entries_by_pattern_type(pattern_type);
   173→        if entries.is_empty() {
   174→            return 0.0;
   175→        }
   176→
   177→        let successful = entries.iter().filter(|e| e.success).count();
   178→        (successful as f64) / (entries.len() as f64)
   179→    }
   180→
   181→    fn get_average_recovery_time(&self, pattern_type: &str) -> u32 {
   182→        let entries = self.get_entries_by_pattern_type(pattern_type);
   183→        if entries.is_empty() {
   184→            return 0;
   185→        }
   186→
   187→        let total_time: u32 = entries.iter().map(|e| e.recovery_time_ms).sum();
   188→        total_time / entries.len() as u32
   189→    }
   190→
   191→    fn get_average_improvement(&self, pattern_type: &str) -> f64 {
   192→        let entries = self.get_entries_by_pattern_type(pattern_type);
   193→        if entries.is_empty() {
   194→            return 0.0;
   195→        }
   196→
   197→        let total_improvement: f64 = entries.iter().map(|e| e.improvement_ratio()).sum();
   198→        total_improvement / entries.len() as f64
   199→    }
   200→
   201→    fn query_by_saturation_range(&self, min: f64, max: f64) -> Vec<&RecoveryHistoryEntry> {
   202→        self.entries
   203→            .iter()
   204→            .filter(|e| e.saturation_before >= min && e.saturation_before <= max)
   205→            .collect()
   206→    }
   207→
   208→    fn query_by_time_range(&self, start_timestamp: u64, end_timestamp: u64) -> Vec<&RecoveryHistoryEntry> {
   209→        self.entries
   210→            .iter()
   211→            .filter(|e| e.timestamp >= start_timestamp && e.timestamp <= end_timestamp)
   212→            .collect()
   213→    }
   214→
   215→    fn query_by_recovery_time_range(
   216→        &self,
   217→        min_time: u32,
   218→        max_time: u32,
   219→    ) -> Vec<&RecoveryHistoryEntry> {
   220→        self.entries
   221→            .iter()
   222→            .filter(|e| e.recovery_time_ms >= min_time && e.recovery_time_ms <= max_time)
   223→            .collect()
   224→    }
   225→
   226→    fn query_successful_only(&self) -> Vec<&RecoveryHistoryEntry> {
   227→        self.entries.iter().filter(|e| e.success).collect()
   228→    }
   229→
   230→    fn query_failed_only(&self) -> Vec<&RecoveryHistoryEntry> {
   231→        self.entries.iter().filter(|e| !e.success).collect()
   232→    }
   233→
   234→    fn get_entry_count(&self) -> usize {
   235→        self.entries.len()
   236→    }
   237→
   238→    fn clear(&mut self) {
   239→        self.entries.clear();
   240→    }
   241→
   242→    fn get_pattern_statistics(&self, pattern_type: &str) -> PatternStatistics {
   243→        let entries = self.get_entries_by_pattern_type(pattern_type);
   244→
   245→        if entries.is_empty() {
   246→            return PatternStatistics {
   247→                pattern_type: pattern_type.to_string(),
   248→                total_occurrences: 0,
   249→                success_count: 0,
   250→                failure_count: 0,
   251→                success_rate: 0.0,
   252→                average_recovery_time_ms: 0,
   253→                average_improvement_ratio: 0.0,
   254→                min_recovery_time_ms: 0,
   255→                max_recovery_time_ms: 0,
   256→                last_occurrence_timestamp: 0,
   257→            };
   258→        }
   259→
   260→        let success_count = entries.iter().filter(|e| e.success).count();
   261→        let failure_count = entries.len() - success_count;
   262→
   263→        let total_time: u32 = entries.iter().map(|e| e.recovery_time_ms).sum();
   264→        let average_time = total_time / entries.len() as u32;
   265→
   266→        let total_improvement: f64 = entries.iter().map(|e| e.improvement_ratio()).sum();
   267→        let average_improvement = total_improvement / entries.len() as f64;
   268→
   269→        let min_time = entries.iter().map(|e| e.recovery_time_ms).min().unwrap_or(0);
   270→        let max_time = entries.iter().map(|e| e.recovery_time_ms).max().unwrap_or(0);
   271→
   272→        let last_timestamp = entries.last().map(|e| e.timestamp).unwrap_or(0);
   273→
   274→        PatternStatistics {
   275→            pattern_type: pattern_type.to_string(),
   276→            total_occurrences: entries.len(),
   277→            success_count,
   278→            failure_count,
   279→            success_rate: (success_count as f64) / (entries.len() as f64),
   280→            average_recovery_time_ms: average_time,
   281→            average_improvement_ratio: average_improvement,
   282→            min_recovery_time_ms: min_time,
   283→            max_recovery_time_ms: max_time,
   284→            last_occurrence_timestamp: last_timestamp,
   285→        }
   286→    }
   287→}
