   306→// ============================================================================
   307→// PatternQueryInterface: 패턴 검색 인터페이스
   308→// ============================================================================
   309→
   310→trait PatternQueryInterface {
   311→    fn query_recent(&self, count: usize) -> Vec<&RecoveryHistoryEntry>;
   312→    fn query_by_pattern(&self, pattern_type: &str) -> Vec<&RecoveryHistoryEntry>;
   313→    fn query_by_time(&self, start: u64, end: u64) -> Vec<&RecoveryHistoryEntry>;
   314→    fn get_statistics(&self, pattern_type: &str) -> PatternStatistics;
   315→}
   316→
   317→impl PatternQueryInterface for RecoveryHistoryDB {
   318→    fn query_recent(&self, count: usize) -> Vec<&RecoveryHistoryEntry> {
   319→        self.get_recent_entries(count)
   320→    }
   321→
   322→    fn query_by_pattern(&self, pattern_type: &str) -> Vec<&RecoveryHistoryEntry> {
   323→        self.get_entries_by_pattern_type(pattern_type)
   324→    }
   325→
   326→    fn query_by_time(&self, start: u64, end: u64) -> Vec<&RecoveryHistoryEntry> {
   327→        self.query_by_time_range(start, end)
   328→    }
   329→
   330→    fn get_statistics(&self, pattern_type: &str) -> PatternStatistics {
   331→        self.get_pattern_statistics(pattern_type)
   332→    }
   333→}
