   150→    /// 복구 이력 기록
   151→    pub fn record_recovery(
   152→        &mut self,
   153→        pattern_type: String,
   154→        saturation_before: f64,
   155→        saturation_after: f64,
   156→        recovery_time_ms: u32,
   157→        success: bool,
   158→        recovery_action: String,
   159→        timestamp: u64,
   160→    ) {
   161→        let mut entry = RecoveryHistoryEntry::new(
   162→            0,
   163→            timestamp,
   164→            pattern_type.clone(),
   165→            saturation_before,
   166→            recovery_action,
   167→        );
   168→        entry.complete_recovery(saturation_after, recovery_time_ms, success);
   169→
   170→        self.history_db.add_entry(entry);
   171→        self.total_recoveries_recorded += 1;
   172→    }
